471	function assertFileExists(targetPath: string) {
472	  if (!fs.existsSync(targetPath)) {
473	    throw new Error(`File not found: ${targetPath}`);
474	  }
475	}
476	
477	function parseAndValidateThresholds(thresholdStrings: string[] | undefined): { parsed: Record<string, number>; error?: string } {
478	  if (!thresholdStrings || thresholdStrings.length === 0) {
479	    return { parsed: {} };
480	  }
481	
482	  const parsed: Record<string, number> = {};
483	  const validMetricIds = ['exact_match', 'toxicity', 'length_variance'];
484	
485	  for (const threshold of thresholdStrings) {
486	    const match = threshold.match(/^([a-z_]+)=([0-9.]+)$/);
487	    if (!match) {
488	      return {
489	        parsed: {},
490	        error: `Malformed threshold: '${threshold}'. Expected format: <metric>=<number> (e.g., exact_match=0.9)`
491	      };
492	    }
493	
494	    const [, metricId, minStr] = match;
495	    const min = Number.parseFloat(minStr);
496	
497	    if (Number.isNaN(min) || min < 0 || min > 1) {
498	      return {
499	        parsed: {},
500	        error: `Invalid threshold value for '${metricId}': ${minStr}. Minimum must be a number between 0 and 1.`
501	      };
502	    }
503	
504	    if (!validMetricIds.includes(metricId)) {
505	      return {
506	        parsed: {},
507	        error: `Unknown metric: '${metricId}'. Valid metrics are: ${validMetricIds.join(', ')}.`
508	      };
509	    }
510	
511	    parsed[metricId] = min;
512	  }
513	
514	  return { parsed };
515	}
516	
517	function runEvalCommand(options: EvalOptions) {
518	  assertFileExists(options.outputs);
519	
520	  const thresholdValidation = parseAndValidateThresholds(options.threshold);
521	  if (thresholdValidation.error) {
522	    log.error(thresholdValidation.error);
523	    process.exit(2);
524	  }
525	
526	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
527	    outputsPath: options.outputs,
528	    referencesPath: options.references
529	  });
530	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
531	    outputs: dataset.outputs,
532	    references: dataset.references
533	  });
534	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
535	    evaluations,
536	    outputsPath: dataset.outputsPath,
537	    referencesPath: dataset.referencesPath,
538	    thresholds: thresholdValidation.parsed
539	  });
540	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
541	    report,
542	    format: options.format ?? 'json',
543	    reportPath: options.report
544	  });
545	  log.success('Evaluation report generated.', { path: resolvedPath });
546	
547	  if (report.passed === false) {
