#!/usr/bin/env node

import fs from 'fs';
import path from 'path';
import os from 'os';
import { fileURLToPath } from 'url';
import { Eval } from './packages/frai-core/src/eval/index.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Test data
const outputs = [
  'hello world',
  'foo bar',
  'test case'
];

const references = [
  'hello world',
  'foo bar',
  'test case'
];

// Create temp directory and files
const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-test-'));
const outputsFile = path.join(tmpDir, 'outputs.json');
const referencesFile = path.join(tmpDir, 'references.json');

fs.writeFileSync(outputsFile, JSON.stringify(outputs));
fs.writeFileSync(referencesFile, JSON.stringify(references));

try {
  console.log('Integration Test: Full threshold flow\n');

  // Load data
  const dataset = Eval.loadDataset({
    outputsPath: outputsFile,
    referencesPath: referencesFile
  });
  console.log('✓ Loaded dataset');

  // Run evaluations
  const evaluations = Eval.runEvaluations({
    outputs: dataset.outputs,
    references: dataset.references
  });
  console.log('✓ Ran evaluations');

  // Test 1: Report with passing thresholds
  const reportPass = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: {
      exact_match: 0.5,
      length_variance: 0.5
    }
  });

  if (reportPass.passed === true && reportPass.thresholds.every(t => t.passed)) {
    console.log('✓ Report with passing thresholds works');
  } else {
    console.error('✗ Report with passing thresholds failed');
    console.log(JSON.stringify(reportPass.thresholds, null, 2));
  }

  // Test 2: Report with failing thresholds
  const reportFail = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: {
      exact_match: 0.99,
      length_variance: 0.99
    }
  });

  if (reportFail.passed === false && reportFail.thresholds.some(t => !t.passed)) {
    console.log('✓ Report with failing thresholds works');
  } else {
    console.error('✗ Report with failing thresholds failed');
  }

  // Test 3: Backward compatibility - no thresholds
  const reportNoThresholds = Eval.generateReport({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath
  });

  if (!reportNoThresholds.hasOwnProperty('passed') && !reportNoThresholds.hasOwnProperty('thresholds')) {
    console.log('✓ Backward compatibility (no thresholds) works');
  } else {
    console.error('✗ Backward compatibility check failed');
  }

  // Test 4: Write JSON report with thresholds
  const jsonReportPath = path.join(tmpDir, 'report.json');
  Eval.writeReport({
    report: reportFail,
    format: 'json',
    reportPath: jsonReportPath
  });

  const jsonContent = JSON.parse(fs.readFileSync(jsonReportPath, 'utf8'));
  if (jsonContent.passed === false && Array.isArray(jsonContent.thresholds)) {
    console.log('✓ JSON report with thresholds writes correctly');
  } else {
    console.error('✗ JSON report failed');
  }

  // Test 5: Write Markdown report with thresholds
  const mdReportPath = path.join(tmpDir, 'report.md');
  Eval.writeReport({
    report: reportFail,
    format: 'markdown',
    reportPath: mdReportPath
  });

  const mdContent = fs.readFileSync(mdReportPath, 'utf8');
  if (mdContent.includes('## Thresholds') && mdContent.includes('FAIL')) {
    console.log('✓ Markdown report with thresholds writes correctly');
  } else {
    console.error('✗ Markdown report failed');
  }

  console.log('\n✓ All integration tests passed!');

} catch (error) {
  console.error('✗ Integration test failed:', error.message);
  process.exit(1);
} finally {
  // Cleanup
  fs.rmSync(tmpDir, { recursive: true, force: true });
}

