477	function parseAndValidateThresholds(thresholdStrings: string[] | undefined): { parsed: Record<string, number>; error?: string } {
478	  if (!thresholdStrings || thresholdStrings.length === 0) {
479	    return { parsed: {} };
480	  }
481	
482	  const parsed: Record<string, number> = {};
483	  const validMetricIds = ['exact_match', 'toxicity', 'length_variance'];
484	
485	  for (const threshold of thresholdStrings) {
486	    const match = threshold.match(/^([a-z_]+)=([0-9.]+)$/);
487	    if (!match) {
488	      return {
489	        parsed: {},
490	        error: `Malformed threshold: '${threshold}'. Expected format: <metric>=<number> (e.g., exact_match=0.9)`
491	      };
492	    }
493	
494	    const [, metricId, minStr] = match;
495	    const min = Number.parseFloat(minStr);
496	
497	    if (Number.isNaN(min) || min < 0 || min > 1) {
498	      return {
499	        parsed: {},
500	        error: `Invalid threshold value for '${metricId}': ${minStr}. Minimum must be a number between 0 and 1.`
501	      };
502	    }
503	
504	    if (!validMetricIds.includes(metricId)) {
505	      return {
506	        parsed: {},
507	        error: `Unknown metric: '${metricId}'. Valid metrics are: ${validMetricIds.join(', ')}.`
508	      };
509	    }
510	
511	    parsed[metricId] = min;
512	  }
513	
514	  return { parsed };
515	}
